// Creator Partner Program — documents that are for PARTNERS only (not public/).
//
// The program terms PDF and the creator media-kit PDF are served through an
// authenticated route (app/api/creator-partner/[doc]/route.ts) rather than
// from public/: they're documents for signed-in partners, and each must only
// appear once the owner has approved a version that matches what the platform
// actually does (see the Terms tab and docs/DOCUMENTATION.md "Creator Partner
// Program"). Brand IMAGES meant to be shared freely live in
// public/brand/partner/ instead.
//
// They live OUTSIDE the repo and the build — same env-override-with-prod-
// default pattern as BOARD_UPLOAD_DIR (lib/board-shared.ts) — so publishing or
// replacing one is a file copy, not a deploy:
//   install -o nxeon -m 0644 approved.pdf /opt/nxeon/partner-files/creator-partner-terms.pdf
//   install -o nxeon -m 0644 kit.pdf      /opt/nxeon/partner-files/creator-media-kit.pdf
// No file there = no download button for it.

import { promises as fs } from "node:fs";
import { join } from "node:path";

export const PARTNER_FILES_DIR = process.env.NXEON_PARTNER_FILES_DIR ?? "/opt/nxeon/partner-files";

export const PARTNER_DOCS = {
  terms: { file: "creator-partner-terms.pdf", download: "Nxeon-Creator-Partner-Terms.pdf" },
  "media-kit": { file: "creator-media-kit.pdf", download: "Nxeon-Creator-Media-Kit.pdf" },
} as const;
export type PartnerDocKey = keyof typeof PARTNER_DOCS;

export function isPartnerDoc(k: string): k is PartnerDocKey {
  return Object.prototype.hasOwnProperty.call(PARTNER_DOCS, k);
}

export function partnerDocPath(k: PartnerDocKey): string {
  return join(PARTNER_FILES_DIR, PARTNER_DOCS[k].file);
}

export type PartnerDocInfo = { sizeBytes: number; updatedAt: string };

/** Size + mtime of a published partner document, or null when none is published. */
export async function partnerDocInfo(k: PartnerDocKey): Promise<PartnerDocInfo | null> {
  try {
    const st = await fs.stat(partnerDocPath(k));
    if (!st.isFile() || st.size === 0) return null;
    return { sizeBytes: st.size, updatedAt: st.mtime.toISOString() };
  } catch {
    return null;
  }
}
