import { promises as fs } from "node:fs";
import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { PARTNER_DOCS, isPartnerDoc, partnerDocPath } from "@/lib/partner-files";

export const dynamic = "force-dynamic";

/**
 * Creator Partner Program documents (/api/creator-partner/terms,
 * /api/creator-partner/media-kit) — partners (and admins) only. Not in
 * public/: see lib/partner-files.ts for why and where the files live.
 * 404 (not 403) for a signed-in non-partner so the route doesn't advertise
 * itself; 404 too when no approved file has been published.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ doc: string }> }) {
  const { doc } = await params;
  if (!isPartnerDoc(doc)) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "Sign in first." }, { status: 401 });
  if (user.role !== "ADMIN") {
    const partner = await db.referralPartner.findUnique({ where: { userId: user.id }, select: { id: true } });
    if (!partner) return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  let buf: Buffer;
  try {
    buf = await fs.readFile(partnerDocPath(doc));
  } catch {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  // Refuse to serve anything that isn't actually a PDF, whatever was copied there.
  if (buf.subarray(0, 5).toString("latin1") !== "%PDF-") {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  return new NextResponse(new Uint8Array(buf), {
    headers: {
      "content-type": "application/pdf",
      "content-disposition": `attachment; filename="${PARTNER_DOCS[doc].download}"`,
      "cache-control": "private, no-store",
      "x-content-type-options": "nosniff",
    },
  });
}
