// The Partner Program page's tabs (/dashboard/partner?tab=…). Plain module —
// NOT in the "use client" PartnerView file — because the server page needs the
// real array to validate `?tab=`; a value imported from a client module into a
// server component is a client reference, not the array.

export const PARTNER_TABS = ["overview", "analytics", "customers", "payouts", "media", "terms", "settings"] as const;
export type PartnerTab = (typeof PARTNER_TABS)[number];

export const PARTNER_TAB_META: Record<PartnerTab, { label: string; icon: string }> = {
  overview: { label: "Overview", icon: "grid" },
  analytics: { label: "Analytics", icon: "linechart" },
  customers: { label: "Customers", icon: "users2" },
  payouts: { label: "Payouts", icon: "card" },
  media: { label: "Media kit", icon: "download" },
  terms: { label: "Terms", icon: "file" },
  settings: { label: "Settings", icon: "gear" },
};

export function isPartnerTab(v: string | null | undefined): v is PartnerTab {
  return (PARTNER_TABS as readonly string[]).includes(v ?? "");
}
