import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { computePartnerSummary, partnerFunnel } from "@/lib/partner-commission";
import { partnerPreviewForUser } from "@/lib/partner-pricing";
import { computePartnerAnalytics, partnerEarliestActivity, resolveRange } from "@/lib/partner-analytics";
import { partnerPayoutView } from "@/lib/partner-payout-store";
import { partnerDocInfo } from "@/lib/partner-files";
import { PartnerView, type PartnerInfo } from "@/components/nx/PartnerView";
import { isPartnerTab, type PartnerTab } from "@/lib/nx/partner-tabs";
import { maskEmail } from "@/lib/mask-email";

export const dynamic = "force-dynamic";

/**
 * Partner-facing portal for an agency / KOL, in the Nexion frame.
 *
 * 2026-09-27: split into tabs (Overview, Analytics, Customers, Payouts, Media
 * kit, Terms, Settings), driven by `?tab=` so a tab is linkable and survives a
 * refresh. Analytics reads `?range=7d|30d|90d|12m|all|custom&from=&to=` and is
 * computed here, server-side, off the real ledgers (lib/partner-analytics.ts).
 * The tab is resolved HERE and passed down as a prop — reading the URL inside
 * a useState initialiser is the hydration-mismatch anti-pattern CLAUDE.md
 * warns about.
 */
export default async function PartnerPortalPage({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string; range?: string; from?: string; to?: string; welcome?: string }>;
}) {
  const user = await requireUser();
  const sp = await searchParams;
  const partner = await db.referralPartner.findUnique({ where: { userId: user.id } });

  if (!partner) {
    // Not a partner themselves — but may still be a referred CUSTOMER of
    // someone else's partner link (a distinct relationship, see PartnerView's
    // doc comment).
    const discount = await partnerPreviewForUser(user.id);
    return <PartnerView partner={null} discount={discount} />;
  }

  const tab: PartnerTab = isPartnerTab(sp.tab) ? sp.tab : "overview";
  const earliest = await partnerEarliestActivity(partner);
  const range = resolveRange(sp, earliest);

  const [summary, funnel, customers, perCustomer, chargeCounts, commissions, payouts, analytics, payout, termsPdf, mediaKitPdf] = await Promise.all([
    computePartnerSummary(partner.id),
    partnerFunnel(partner.id, partner.code),
    db.partnerCustomer.findMany({
      where: { partnerId: partner.id },
      orderBy: { attachedAt: "desc" },
      take: 500,
      include: { customer: { select: { name: true, email: true } } },
    }),
    // One grouped query instead of one aggregate per customer.
    db.partnerCommission.groupBy({
      by: ["customerId"],
      where: { partnerId: partner.id, status: { not: "VOID" } },
      _sum: { amountCents: true },
      _min: { createdAt: true },
    }),
    // Charge COUNT per customer: original commission rows only — a refund
    // reversal (kind REFUND) is not another charge.
    db.partnerCommission.groupBy({
      by: ["customerId"],
      where: { partnerId: partner.id, status: { not: "VOID" }, kind: { not: "REFUND" } },
      _count: { _all: true },
    }),
    db.partnerCommission.findMany({
      where: { partnerId: partner.id },
      orderBy: { createdAt: "desc" },
      take: 100,
      include: { customer: { select: { name: true, email: true } } },
    }),
    db.partnerPayout.findMany({ where: { partnerId: partner.id }, orderBy: { createdAt: "desc" }, take: 100 }),
    computePartnerAnalytics(partner, range),
    partnerPayoutView(partner.id),
    partnerDocInfo("terms"),
    partnerDocInfo("media-kit"),
  ]);
  const grants = await db.partnerGrant.findMany({ where: { partnerId: partner.id }, orderBy: { createdAt: "desc" }, take: 10 });
  const byCustomer = new Map(perCustomer.map((p) => [p.customerId, p]));
  const chargesByCustomer = new Map(chargeCounts.map((p) => [p.customerId, p._count._all]));

  const s = summary!;
  const appUrl = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");

  const info: PartnerInfo = {
    name: partner.name,
    code: partner.code,
    ratePct: partner.commissionRatePct,
    type: partner.type ?? null,
    status: partner.status,
    // The REAL partner link — /partner/<code> (app/partner/[code]/route.ts),
    // which records a click before redirecting.
    link: `${appUrl}/partner/${partner.code}`,
    customerCount: s.customerCount,
    lifetimeCents: s.lifetimeCents,
    outstandingCents: s.outstandingCents,
    balanceCents: s.balanceCents,
    paidCents: s.paidCents,
    clicked: funnel.clicked,
    signedUp: funnel.signedUp,
    converted: funnel.converted,
    customers: customers.map((c) => {
      const agg = byCustomer.get(c.customerId);
      return {
        id: c.id,
        name: c.customer.name ?? "",
        // Masked BEFORE serialisation: the raw address never reaches the
        // partner's browser (lib/mask-email.ts). Admin views read User.email
        // directly and stay unmasked.
        email: maskEmail(c.customer.email),
        attachedAt: c.attachedAt.toISOString(),
        firstPaidAt: agg?._min.createdAt?.toISOString() ?? null,
        charges: chargesByCustomer.get(c.customerId) ?? 0,
        earnedCents: agg?._sum.amountCents ?? 0,
      };
    }),
    commissions: commissions.map((c) => ({
      id: c.id,
      when: c.createdAt.toISOString(),
      customer: c.customer.name || maskEmail(c.customer.email),
      kind: c.kind,
      amountCents: c.amountCents,
      status: c.status,
    })),
    payouts: payouts.map((p) => ({
      id: p.id,
      when: p.createdAt.toISOString(),
      amountCents: p.amountCents,
      note: p.note,
    })),
    analytics,
    payout,
    termsPdf,
    mediaKitPdf,
    grants: grants.map((g) => ({ id: g.id, serverId: g.serverId, game: g.game, planName: g.planName, status: g.status, onExpiry: g.onExpiry, expiresAt: g.expiresAt?.toISOString() ?? null })),
  };

  return <PartnerView partner={info} initialTab={tab} welcome={sp.welcome === "1"} />;
}

