/** Mirrors `partnerPreviewForUser`'s return shape (lib/partner-pricing.ts) —
 *  the VIEWER's own standing attachment as a referred customer, relevant only
 *  when they are not themselves a partner (see `ApplyLanding` below). A
 *  customer can be one or the other, never both, so this and `PartnerInfo`
 *  are never both meaningful at once. */
export type PartnerDiscount = { active: boolean; tier: "FIRST" | "RECURRING" | "NONE"; percent: number; partnerName: string | null };

export type PartnerInfo = {
  name: string;
  code: string;
  ratePct: number;
  type: string | null;
  status: string;
  link: string;
  customerCount: number;
  lifetimeCents: number;
  outstandingCents: number;
  paidCents: number;
  /** Signed balance (earned - paid). Negative only when a refunded charge's
   *  commission had already been paid out — it comes off the next payout. */
  balanceCents: number;
  /** Real click/signup/conversion counts — see lib/partner-commission.ts partnerFunnel. */
  clicked: number;
  signedUp: number;
  converted: number;
  /** `email` is MASKED server-side (lib/mask-email.ts) — customers never agreed to
   *  have their address shown to a creator. `id` is the PartnerCustomer row id,
   *  a stable key now that two masked emails can read the same. */
  customers: { id: string; name: string; email: string; attachedAt: string; firstPaidAt: string | null; charges: number; earnedCents: number }[];
  commissions: { id: string; when: string; customer: string; kind: string; amountCents: number; status: string }[];
  payouts: { id: string; when: string; amountCents: number; note: string | null }[];
  /** Date-ranged analytics for the Analytics tab — lib/partner-analytics.ts. */
  analytics: PartnerAnalytics;
  /** Contact details + MASKED payout preference — lib/partner-payout-store.ts. */
  payout: PartnerPayoutView;
  /** The approved terms / media-kit PDFs, when published (lib/partner-files.ts). */
  termsPdf: { sizeBytes: number; updatedAt: string } | null;
  mediaKitPdf: { sizeBytes: number; updatedAt: string } | null;
  /** Free game servers Nxeon granted this partner (lib/partner-grants.ts) — omitted/empty when none. */
  grants?: { id: string; serverId: string | null; game: string; planName: string; status: string; onExpiry: string; expiresAt: string | null }[];
};

export function PartnerView({
  partner, discount, initialTab = "overview", welcome = false,
}: { partner: PartnerInfo | null; discount?: PartnerDiscount; initialTab?: PartnerTab; welcome?: boolean }) {
  return (
    <>
      <PartnerAurora />
      <div className="relative z-10 mx-auto flex w-full max-w-[1520px] flex-col gap-4">
        {partner ? <PartnerDashboard partner={partner} initialTab={initialTab} welcome={welcome} /> : <ApplyLanding discount={discount} />}
      </div>
    </>
  );
}

/* ── Not a partner yet ─────────────────────────────────────────────────── */
function PartnerDashboard({ partner, initialTab, welcome }: { partner: PartnerInfo; initialTab: PartnerTab; welcome: boolean }) {
  const sp = useSearchParams();
  // The URL is the source of truth once hydrated (back/forward, a range
  // change's router.push); `initialTab` is the server's own reading of the
  // same URL, so first paint and hydration agree.
  const fromUrl = sp.get("tab");
  const tab: PartnerTab = isPartnerTab(fromUrl) ? fromUrl : fromUrl === null ? initialTab : "overview";
  const tier = tierFor(partner.ratePct);
  const typeName = PARTNER_TYPES.find((t) => t.key === partner.type)?.name ?? partner.type;
  const tabRefs = useRef<Partial<Record<PartnerTab, HTMLButtonElement | null>>>({});

  const select = (t: PartnerTab, focus = false) => {
    const params = new URLSearchParams(window.location.search);
    if (t === "overview") params.delete("tab");
    else params.set("tab", t);
    const qs = params.toString();
    // Native history API — Next keeps useSearchParams in sync with it, and a
    // tab switch needs no server round trip (every tab's data is already here).
    window.history.pushState(null, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
    if (focus) tabRefs.current[t]?.focus();
  };

  useEffect(() => {
    tabRefs.current[tab]?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [tab]);

  const onKey = (e: React.KeyboardEvent) => {
    const i = PARTNER_TABS.indexOf(tab);
    let next: number | null = null;
    if (e.key === "ArrowRight") next = (i + 1) % PARTNER_TABS.length;
    else if (e.key === "ArrowLeft") next = (i - 1 + PARTNER_TABS.length) % PARTNER_TABS.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = PARTNER_TABS.length - 1;
    if (next === null) return;
    e.preventDefault();
    select(PARTNER_TABS[next], true);
  };

  return (
    <>
      <header className="relative flex flex-col gap-4 pb-1 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex min-w-0 max-w-[600px] flex-col gap-3">
          <span className="text-[12.5px] font-extrabold uppercase tracking-[0.24em] text-magenta">Partner Program</span>
          <h1 className="text-[36px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[46px]">
            Build. Promote.
            <br />
            <span className="bg-gradient-to-r from-[#5fd0ff] via-[#a855f7] to-[#f21cff] bg-clip-text text-transparent">
              Earn.
            </span>
          </h1>
          <p className="max-w-[54ch] text-[13.5px] leading-[1.6] text-tx-mute">
            Every customer attached to your link or code, and every commission it's earned.
          </p>
        </div>
        <span className="flex flex-none flex-wrap items-center gap-1.5">
          <span className="chip-tone chip-violet">{tier.name} tier</span>
          {typeName && <span className="chip-tone chip-blue">{typeName}</span>}
          <span className={"chip-tone " + (partner.status === "ACTIVE" ? "chip-mint" : "chip-slate")}>
            {partner.status === "ACTIVE" ? "Active" : partner.status}
          </span>
        </span>
      </header>

      {welcome && (
        <div role="status" className="flex flex-wrap items-center gap-2.5 rounded-[12px] border border-[rgba(17,200,142,0.3)] bg-[rgba(17,200,142,0.08)] px-4 py-3">
          <Icon name="handshake" size={16} tone="mint" className="flex-none" />
          <span className="text-[12.5px] font-semibold text-white">
            Welcome aboard — your sponsor code is <span className="mono">{partner.code}</span> and your link is live. Add
            your contact details and payout method below so we know where to send your commission.
          </span>
        </div>
      )}

      <div
        role="tablist"
        aria-label="Partner program sections"
        onKeyDown={onKey}
        className="nx-partner-tabs flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {PARTNER_TABS.map((t) => {
          const on = tab === t;
          const meta = PARTNER_TAB_META[t];
          return (
            <button
              key={t}
              ref={(el) => { tabRefs.current[t] = el; }}
              type="button"
              role="tab"
              id={`partner-tab-${t}`}
              aria-selected={on}
              aria-controls={`partner-panel-${t}`}
              tabIndex={on ? 0 : -1}
              onClick={() => select(t)}
              className={
                "flex flex-none items-center gap-2 rounded-[10px] border px-3.5 py-2 text-[13px] font-bold transition outline-none focus-visible:ring-2 focus-visible:ring-[#8b5cff]/70 " +
                (on
                  ? "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))] text-white"
                  : "border-transparent text-tx-dim hover:bg-white/[0.04] hover:text-white")
              }
            >
              <Icon name={meta.icon} size={14} tone="inherit" className={on ? "text-white" : "text-[#7f9ad0]"} />
              {meta.label}
            </button>
          );
        })}
      </div>

      <div
