// Creator Partner Program — per-creator MEDIA KITS (sponsored-segment videos).
//
// The owner cuts a sponsored segment for a creator (sometimes in several
// languages), with an end-frame still and a HOW-TO-USE.txt. Each partner sees
// their OWN kit plus a generic English cut for everyone, on the "Media kit" tab
// of /dashboard/partner. Files are served by the authenticated, Range-capable
// route app/api/creator-partner/kits/[code]/[file]/route.ts (zip of a whole
// kit: app/api/creator-partner/kits/[code]/route.ts).
//
// Layout — under the same out-of-repo dir as the partner PDFs
// (lib/partner-files.ts, `NXEON_PARTNER_FILES_DIR`), so publishing is a file
// copy, never a deploy:
//
//   <PARTNER_FILES_DIR>/kits/<CODE>/      one folder per ReferralPartner.code (UPPERCASE)
//   <PARTNER_FILES_DIR>/kits/_generic/    shown to every partner
//
//   nxeon-promo_<CODE>_<lang>_16x9.mp4            the video, one per language
//   nxeon-promo_<CODE>_<lang>_16x9_endframe.png   its end frame (optional; poster + download)
//   HOW-TO-USE.txt                                the guide, parsed into UI by parseKitGuide()
//
// SECURITY: the URL can only ever name a file that is IN the directory
// listing (an exact-match whitelist), the code is validated against a strict
// pattern before it touches a path, and nothing but regular files with a known
// extension is listed (symlinks and subdirectories are skipped). See
// resolveKitFile().

import { promises as fs } from "node:fs";
import { join } from "node:path";
import { PARTNER_FILES_DIR } from "./partner-files";

export const KITS_DIR = join(PARTNER_FILES_DIR, "kits");
export const GENERIC_KIT = "_generic";
export const GUIDE_FILE = "HOW-TO-USE.txt";

const CODE_RE = /^[A-Z0-9-]{2,20}$/;
/** A plain file name: no separators, no leading dot, no "..". */
const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/;

export const KIT_CONTENT_TYPES: Record<string, string> = {
  mp4: "video/mp4",
  webm: "video/webm",
  mov: "video/quicktime",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  txt: "text/plain; charset=utf-8",
  pdf: "application/pdf",
};

/** Display names for the language tags in the file names. */
export const KIT_LANGUAGES: Record<string, string> = {
  en: "English",
  tr: "Turkish",
  tl: "Filipino (Tagalog)",
  es: "Spanish",
  hi: "Hindi",
  pt: "Portuguese",
  de: "German",
  fr: "French",
  it: "Italian",
  ru: "Russian",
  ar: "Arabic",
  id: "Indonesian",
  ja: "Japanese",
  ko: "Korean",
  pl: "Polish",
  vi: "Vietnamese",
  th: "Thai",
  nl: "Dutch",
};

/** A partner code or the generic kit — the only things a kit URL may name. */
export function isKitCode(code: string): boolean {
  return code === GENERIC_KIT || CODE_RE.test(code);
}

export function isSafeKitFileName(name: string): boolean {
  return NAME_RE.test(name) && !name.includes("..") && kitExt(name) in KIT_CONTENT_TYPES;
}

function kitExt(name: string): string {
  const i = name.lastIndexOf(".");
  return i < 0 ? "" : name.slice(i + 1).toLowerCase();
}

export function kitContentType(name: string): string {
  return KIT_CONTENT_TYPES[kitExt(name)] ?? "application/octet-stream";
}

export type KitFile = { name: string; sizeBytes: number; updatedAt: string };

/** The whitelisted files in one kit folder (regular files, known types), sorted. [] when absent. */
export async function listKitFiles(code: string): Promise<KitFile[]> {
  if (!isKitCode(code)) return [];
  const dir = join(KITS_DIR, code);
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  const out: KitFile[] = [];
  for (const e of entries) {
    // Dirent.isFile() is false for a symlink, so a link pointing out of the
    // folder is never listed (and so can never be served).
    if (!e.isFile() || !isSafeKitFileName(e.name)) continue;
    try {
      const st = await fs.lstat(join(dir, e.name));
      if (!st.isFile() || st.size === 0) continue;
      out.push({ name: e.name, sizeBytes: st.size, updatedAt: st.mtime.toISOString() });
    } catch {
      /* vanished between readdir and stat */
    }
  }
  return out.sort((a, b) => a.name.localeCompare(b.name));
}

/**
 * The absolute path of `name` in kit `code` — ONLY if it is in that kit's
 * directory listing (exact match). Anything else (traversal, absolute paths,
 * encoded separators, unknown files) is null.
 */
export async function resolveKitFile(code: string, name: string): Promise<{ path: string; file: KitFile } | null> {
  if (!isKitCode(code) || !isSafeKitFileName(name)) return null;
  const file = (await listKitFiles(code)).find((f) => f.name === name);
  return file ? { path: join(KITS_DIR, code, file.name), file } : null;
}

/* ── grouping ──────────────────────────────────────────────────────────── */

export type KitAsset = {
  /** Language tag from the file name, e.g. "en". */
  lang: string;
  langLabel: string;
  /** "16:9" from "16x9", or null. */
  aspect: string | null;
  video: KitFile;
  endframe: KitFile | null;
};

const ASSET_RE = /^(.+?)_([a-z]{2,3})_(\d{1,2}x\d{1,2})(_endframe)?\.([a-z0-9]+)$/i;
const VIDEO_EXT = new Set(["mp4", "webm", "mov"]);
const IMAGE_EXT = new Set(["png", "jpg", "jpeg", "webp"]);

export function groupKitAssets(files: KitFile[]): { assets: KitAsset[]; others: KitFile[] } {
  const videos = new Map<string, { m: RegExpExecArray; f: KitFile }>();
  const frames = new Map<string, KitFile>();
  const others: KitFile[] = [];
  for (const f of files) {
    if (f.name === GUIDE_FILE) continue;
    const m = ASSET_RE.exec(f.name);
    const ext = kitExt(f.name);
    if (!m) {
      others.push(f);
      continue;
    }
    const key = `${m[1]}_${m[2].toLowerCase()}_${m[3]}`;
    if (!m[4] && VIDEO_EXT.has(ext)) videos.set(key, { m, f });
    else if (m[4] && IMAGE_EXT.has(ext)) frames.set(key, f);
    else others.push(f);
  }
  const assets: KitAsset[] = [];
  for (const [key, { m, f }] of videos) {
    const lang = m[2].toLowerCase();
    assets.push({
      lang,
      langLabel: KIT_LANGUAGES[lang] ?? lang.toUpperCase(),
      aspect: m[3].replace("x", ":"),
      video: f,
      endframe: frames.get(key) ?? null,
    });
    frames.delete(key);
  }
  // An end frame with no video of its own is still a file the creator can use.
  others.push(...frames.values());
  // English first, then alphabetical by label.
  assets.sort((a, b) => (a.lang === "en" ? -1 : b.lang === "en" ? 1 : a.langLabel.localeCompare(b.langLabel)));
  return { assets, others: others.sort((a, b) => a.name.localeCompare(b.name)) };
}

/* ── HOW-TO-USE.txt ────────────────────────────────────────────────────── */

export type KitGuide = {
  title: string | null;
  /** File names listed under "Your files". */
  files: string[];
  /** Any prose under "Your files" (the generic cut explains itself there). */
  filesNote: string | null;
  whatItIs: string | null;
  steps: string[];
  /** The bracketed hint after "Suggested narration", e.g. "timings match the video…". */
  narrationNote: string | null;
  narration: { at: string; text: string }[];
  description: string | null;
  contact: string | null;
  /** Any section this parser doesn't know, kept rather than dropped. */
  extra: { heading: string; body: string }[];
};

type Section = { heading: string; inline: string | null; lines: string[] };

/** Joins wrapped, indented lines into paragraphs (a blank line splits them). */
function paragraphs(lines: string[]): string[] {
  const out: string[] = [];
  let cur: string[] = [];
  for (const l of lines) {
    const t = l.trim();
    if (!t) {
      if (cur.length) out.push(cur.join(" "));
      cur = [];
    } else cur.push(t);
  }
  if (cur.length) out.push(cur.join(" "));
  return out;
}

/**
 * Parses the owner's structured plain-text guide. Format: a title line with an
 * `====` underline, then sections whose heading starts in column 0 and whose
 * body is indented. "Heading: value" on one line is a one-line section.
 * Tolerant — an unknown section lands in `extra`, a missing one is empty.
 */
export function parseKitGuide(raw: string): KitGuide {
  const lines = raw.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").split("\n");
  const g: KitGuide = {
    title: null, files: [], filesNote: null, whatItIs: null, steps: [], narrationNote: null,
    narration: [], description: null, contact: null, extra: [],
  };
  const sections: Section[] = [];
  let i = 0;
  // Title + underline.
  while (i < lines.length && !lines[i].trim()) i++;
  if (i + 1 < lines.length && /^\s*={3,}\s*$/.test(lines[i + 1])) {
    g.title = lines[i].trim();
    i += 2;
  }
  for (; i < lines.length; i++) {
    const l = lines[i];
    if (/^\s*={3,}\s*$/.test(l)) continue;
    if (l.trim() && !/^\s/.test(l)) {
      const m = /^([^:]{1,80}):\s*(.+)$/.exec(l.trim());
      sections.push(m ? { heading: m[1].trim(), inline: m[2].trim(), lines: [] } : { heading: l.trim(), inline: null, lines: [] });
    } else if (sections.length) sections[sections.length - 1].lines.push(l);
  }

  for (const s of sections) {
    const h = s.heading.toLowerCase();
    if (h.startsWith("your files")) {
      const prose: string[] = [];
      for (const l of s.lines) {
        const m = /^\s*[-*•]\s+(.+)$/.exec(l);
        if (m) g.files.push(m[1].trim());
        else prose.push(l);
      }
      g.filesNote = paragraphs(prose).join("\n\n") || null;
    } else if (h.startsWith("what it is")) {
      g.whatItIs = paragraphs(s.lines).join("\n\n") || null;
    } else if (h.startsWith("how to use")) {
      for (const l of s.lines) {
        const m = /^\s*\d+[.)]\s+(.+)$/.exec(l);
        if (m) g.steps.push(m[1].trim());
        else if (l.trim() && g.steps.length) g.steps[g.steps.length - 1] += " " + l.trim();
      }
    } else if (h.startsWith("suggested narration") || h.startsWith("narration")) {
      const note = /\(([^)]+)\)/.exec(s.heading);
      g.narrationNote = note ? note[1].trim() : null;
      for (const l of s.lines) {
        const m = /^\s*(\d{1,2}:\d{2})\s+(.+)$/.exec(l);
        if (m) g.narration.push({ at: m[1], text: m[2].trim() });
        else if (l.trim() && g.narration.length) g.narration[g.narration.length - 1].text += " " + l.trim();
      }
    } else if (h.startsWith("description")) {
      g.description = paragraphs(s.lines).join("\n\n") || s.inline || null;
    } else if (h.startsWith("questions") || h.startsWith("contact")) {
      g.contact = s.inline ?? (paragraphs(s.lines).join(" ") || null);
    } else {
      const body = [s.inline, ...paragraphs(s.lines)].filter(Boolean).join("\n\n");
      if (body) g.extra.push({ heading: s.heading, body });
    }
  }
  return g;
}

/** Fills the generic guide's YOURCODE placeholder with the viewer's real code (display only). */
export function personalizeGuide(g: KitGuide, code: string): KitGuide {
  const r = (s: string | null) => (s == null ? s : s.replace(/YOURCODE/g, code));
  return {
    ...g,
    filesNote: r(g.filesNote),
    whatItIs: r(g.whatItIs),
    steps: g.steps.map((s) => r(s)!),
    narration: g.narration.map((n) => ({ ...n, text: r(n.text)! })),
    description: r(g.description),
    extra: g.extra.map((e) => ({ ...e, body: r(e.body)! })),
  };
}

/* ── one kit, ready for the UI ─────────────────────────────────────────── */

export type PartnerKit = {
  /** The folder: the partner's code, or "_generic". */
  code: string;
  assets: KitAsset[];
  others: KitFile[];
  guide: KitGuide | null;
  /** The raw guide file (for its download link), when present. */
  guideFile: KitFile | null;
  totalBytes: number;
  updatedAt: string | null;
};

const MAX_GUIDE_BYTES = 64 * 1024;

/** One kit folder, grouped + parsed; null when it doesn't exist or holds no video. */
export async function loadKit(code: string): Promise<PartnerKit | null> {
  const files = await listKitFiles(code);
  const { assets, others } = groupKitAssets(files);
  if (assets.length === 0) return null;
  const guideFile = files.find((f) => f.name === GUIDE_FILE) ?? null;
  let guide: KitGuide | null = null;
  if (guideFile && guideFile.sizeBytes <= MAX_GUIDE_BYTES) {
    try {
      guide = parseKitGuide(await fs.readFile(join(KITS_DIR, code, GUIDE_FILE), "utf8"));
    } catch {
      guide = null;
    }
  }
  return {
    code,
    assets,
    others,
    guide,
    guideFile,
    totalBytes: files.reduce((n, f) => n + f.sizeBytes, 0),
    updatedAt: files.reduce<string | null>((m, f) => (!m || f.updatedAt > m ? f.updatedAt : m), null),
  };
}

/**
 * What a partner sees: their own kit (null when none has been made yet or the
 * code isn't a valid kit folder name) and the generic one (YOURCODE filled in
 * with their code in the rendered guide; the raw download stays as-is).
 */
export async function loadPartnerKits(partnerCode: string): Promise<{ personal: PartnerKit | null; generic: PartnerKit | null }> {
  const code = partnerCode.trim().toUpperCase();
  const [personal, generic] = await Promise.all([
    CODE_RE.test(code) ? loadKit(code) : Promise.resolve(null),
    loadKit(GENERIC_KIT),
  ]);
  if (generic?.guide && CODE_RE.test(code)) generic.guide = personalizeGuide(generic.guide, code);
  return { personal, generic };
}

/** URL of one kit file (inline; add `?download=1` for an attachment). */
export function kitFileUrl(code: string, name: string, download = false): string {
  return `/api/creator-partner/kits/${encodeURIComponent(code)}/${encodeURIComponent(name)}${download ? "?download=1" : ""}`;
}

/** URL of a whole kit as one zip. */
export function kitZipUrl(code: string): string {
  return `/api/creator-partner/kits/${encodeURIComponent(code)}`;
}

/* ── streaming zip (STORE, no compression — MP4/PNG don't compress) ───── */

