export async function kitZip(code: string): Promise<{ stream: ReadableStream<Uint8Array>; size: number; filename: string } | null> {
  const files = await listKitFiles(code);
  if (files.length === 0) return null;
  const folder = code === GENERIC_KIT ? "nxeon-sponsored-segment-generic" : `nxeon-sponsored-segment-${code}`;
  const entries = await Promise.all(
    files.map(async (f) => {
