import { createReadStream } from "node:fs";
import { Readable } from "node:stream";
import { NextRequest, NextResponse } from "next/server";
import { kitContentType, resolveKitFile } from "@/lib/partner-kits";
import { kitAccess } from "@/lib/partner-kit-access";

export const dynamic = "force-dynamic";

/**
 * One file of a creator media kit: /api/creator-partner/kits/<CODE|_generic>/<file>.
 * Auth: lib/partner-kit-access.ts (own code + generic for partners, any for
 * billing-area staff; 401 signed out, 404 otherwise). The file must be in the
 * kit folder's listing (lib/partner-kits.ts resolveKitFile) — no path is ever
 * built from the URL alone. Supports a single HTTP Range (bytes=a-b, a-, -n)
 * so the in-page <video> can seek; `?download=1` makes it an attachment.
 * Same response hardening as app/api/board/attachments/[id].
 */
async function serve(req: NextRequest, params: Promise<{ code: string; file: string }>, head: boolean) {
  const { code, file } = await params;
  const access = await kitAccess(code);
  if (!access.ok) {
    return NextResponse.json({ error: access.status === 401 ? "Sign in first." : "Not found" }, { status: access.status });
  }
  const hit = await resolveKitFile(code, file);
  if (!hit) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const size = hit.file.sizeBytes;
  const download = req.nextUrl.searchParams.get("download") === "1";
  const safeName = hit.file.name.replace(/[^A-Za-z0-9._-]/g, "_");
  const base: Record<string, string> = {
    "Content-Type": kitContentType(hit.file.name),
    "Content-Disposition": `${download ? "attachment" : "inline"}; filename="${safeName}"`,
    "Accept-Ranges": "bytes",
    "Cache-Control": "private, no-store",
    "Last-Modified": new Date(hit.file.updatedAt).toUTCString(),
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'none'; sandbox",
  };

  const range = req.headers.get("range");
  if (range) {
    const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
    // Multi-range or malformed: ignore the header and send the whole file (RFC 9110 allows it).
    if (m && (m[1] || m[2])) {
      let start: number;
      let end: number;
      if (!m[1]) {
        // Suffix range: the last N bytes.
        const n = Number(m[2]);
        start = Math.max(0, size - n);
        end = size - 1;
      } else {
        start = Number(m[1]);
        end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
      }
      if (!Number.isSafeInteger(start) || start >= size || start > end) {
        return new NextResponse(null, { status: 416, headers: { ...base, "Content-Range": `bytes */${size}` } });
      }
      const headers = { ...base, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) };
      if (head) return new NextResponse(null, { status: 206, headers });
      const stream = createReadStream(hit.path, { start, end });
      return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, { status: 206, headers });
    }
  }
  const headers = { ...base, "Content-Length": String(size) };
  if (head) return new NextResponse(null, { status: 200, headers });
  const stream = createReadStream(hit.path);
  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, { status: 200, headers });
}

export function GET(req: NextRequest, { params }: { params: Promise<{ code: string; file: string }> }) {
  return serve(req, params, false);
}

export function HEAD(req: NextRequest, { params }: { params: Promise<{ code: string; file: string }> }) {
  return serve(req, params, true);
}
EOF
