"use client";

import { useState } from "react";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { kitFileUrl, kitZipUrl } from "@/lib/partner-kit-urls";
import type { KitAsset, KitGuide, PartnerKit } from "@/lib/partner-kits";

/* The "Your sponsored segment" + "Generic English version" blocks at the top of
   the partner portal's Media kit tab. Data comes from lib/partner-kits.ts
   (loaded server-side in app/dashboard/partner/page.tsx); every file is served
   by the authenticated route app/api/creator-partner/kits/[code]/[file]. */

export type PartnerKits = { personal: PartnerKit | null; generic: PartnerKit | null };

export function SponsoredSegmentBlocks({ kits, code }: { kits: PartnerKits; code: string }) {
  const { personal, generic } = kits;
  if (!personal && !generic) return null;
  return (
    <>
      {personal && (
        <Panel
          title="Your sponsored segment"
          sub={`Made for your channel, with your code ${code} on screen. ${langCount(personal)} · ${fmtSize(personal.totalBytes)}`}
          action={<ZipButton kit={personal} primary />}
        >
          <KitBody kit={personal} guideOpen />
        </Panel>
      )}
      {generic && (
        <Panel
          title="Generic English version"
          sub="No creator code on screen. Use it for any video, and say your own code where the guide does."
          action={<ZipButton kit={generic} primary={!personal} />}
        >
          {!personal && (
            <div role="status" className="flex items-start gap-2.5 rounded-[12px] border border-[rgba(95,208,255,0.3)] bg-[rgba(95,208,255,0.07)] px-3.5 py-2.5">
              <Icon name="sparkles" size={15} tone="cyan" className="mt-[1px] flex-none" />
              <span className="text-[12.5px] leading-relaxed text-tx-dim">
                Your personal version, with your code <b className="mono text-white">{code}</b> on screen, is on the
                way. It will appear here as soon as it&apos;s ready. Until then, use this one.
              </span>
            </div>
          )}
          <div className={!personal ? "mt-3" : ""}>
            <KitBody kit={generic} guideOpen={!personal} />
          </div>
        </Panel>
      )}
    </>
  );
}

function langCount(kit: PartnerKit): string {
  const n = kit.assets.length;
  return n === 1 ? `1 language (${kit.assets[0].langLabel})` : `${n} languages`;
}

function ZipButton({ kit, primary }: { kit: PartnerKit; primary?: boolean }) {
  return (
    <a
      href={kitZipUrl(kit.code)}
      download
      className={(primary ? "btn-primary" : "btn-secondary") + " hidden h-[38px] flex-none gap-2 px-3.5 text-[12.5px] sm:inline-flex"}
    >
      <Icon name="download" size={14} tone="inherit" /> Download everything
      <span className="font-semibold opacity-75">({fmtSize(kit.totalBytes)} .zip)</span>
    </a>
  );
}

function KitBody({ kit, guideOpen }: { kit: PartnerKit; guideOpen: boolean }) {
  const g = kit.guide;
  const odd = kit.assets.length % 2 === 1;
  return (
    <div className="flex min-w-0 flex-col gap-3">
      {/* The header action is hidden at phone width — the full-width button lives here instead. */}
      <a href={kitZipUrl(kit.code)} download className="btn-secondary h-[40px] gap-2 px-3.5 text-[12.5px] sm:hidden">
        <Icon name="download" size={14} tone="inherit" /> Download everything ({fmtSize(kit.totalBytes)} .zip)
      </a>

      <div className="grid min-w-0 gap-3 md:grid-cols-2">
        {kit.assets.map((a) => (
          <VideoCard key={a.video.name} code={kit.code} asset={a} />
        ))}
        {odd && <AboutCard guide={g} kit={kit} />}
      </div>

      {g && (
        guideOpen ? (
          <GuideBlocks guide={g} kit={kit} showAbout={!odd} />
        ) : (
          <details className="group rounded-[12px] border border-rim-soft bg-well">
            <summary className="flex cursor-pointer list-none items-center gap-2 px-3.5 py-3 text-[12.5px] font-bold text-white [&::-webkit-details-marker]:hidden">
              <Icon name="file" size={14} className="flex-none" />
              How to use it, narration and description text
              <span className="ml-auto text-[11.5px] font-semibold text-cyan group-open:hidden">Show</span>
              <span className="ml-auto hidden text-[11.5px] font-semibold text-cyan group-open:inline">Hide</span>
            </summary>
            <div className="border-t border-rim-soft p-3">
              <GuideBlocks guide={g} kit={kit} showAbout={!odd} />
            </div>
          </details>
        )
      )}

      {kit.others.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 text-[12px]">
          <span className="text-tx-faint">Other files</span>
          {kit.others.map((f) => (
            <a key={f.name} href={kitFileUrl(kit.code, f.name, true)} className="mono truncate rounded-[8px] border border-rim-soft bg-well px-2.5 py-1 text-[11.5px] text-tx-dim hover:border-[#2f7eef] hover:text-white">
              {f.name} · {fmtSize(f.sizeBytes)}
            </a>
          ))}
        </div>
      )}
    </div>
  );
}

function VideoCard({ code, asset }: { code: string; asset: KitAsset }) {
  return (
    <div className="flex min-w-0 flex-col overflow-hidden rounded-[12px] border border-rim-soft bg-well">
      <div className="nx-dark-island relative aspect-video w-full bg-[#03060f]">
        <video
          controls
          preload="metadata"
          playsInline
          poster={asset.endframe ? kitFileUrl(code, asset.endframe.name) : undefined}
          className="absolute inset-0 h-full w-full bg-[#03060f] object-contain"
          aria-label={`Sponsored segment, ${asset.langLabel}`}
        >
          <source src={kitFileUrl(code, asset.video.name)} type="video/mp4" />
        </video>
      </div>
      <div className="flex flex-col gap-2.5 border-t border-rim-soft px-3.5 py-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[13.5px] font-extrabold tracking-[-0.01em] text-white">{asset.langLabel}</span>
          {asset.aspect && <span className="chip-tone chip-blue">{asset.aspect}</span>}
          <span className="ml-auto text-[11px] text-tx-faint">{fmtSize(asset.video.sizeBytes)}</span>
        </div>
        <div className="flex flex-wrap gap-2">
          <a href={kitFileUrl(code, asset.video.name, true)} className="btn-primary h-[36px] flex-1 gap-2 px-3 text-[12.5px] sm:flex-none">
            <Icon name="video" size={14} tone="inherit" /> Download video
          </a>
          {asset.endframe && (
            <a href={kitFileUrl(code, asset.endframe.name, true)} className="btn-secondary h-[36px] flex-1 gap-2 px-3 text-[12.5px] sm:flex-none">
              <Icon name="download" size={14} tone="inherit" /> Download end frame
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

/** Fills the empty half of the grid when a kit has an odd number of videos. */
function AboutCard({ guide, kit }: { guide: KitGuide | null; kit: PartnerKit }) {
  return (
    <div className="flex min-w-0 flex-col gap-3 rounded-[12px] border border-rim-soft bg-well p-4">
      <SubHead icon="sparkles" title="What it is" />
      <p className="text-[12.5px] leading-relaxed text-tx-mute">
        {guide?.whatItIs ?? "A short sponsored segment showing the real Nxeon game-server flow, ready to drop into your edit."}
      </p>
      {guide?.filesNote && <p className="text-[12px] leading-relaxed text-tx-faint">{guide.filesNote}</p>}
      <FileList kit={kit} />
    </div>
  );
}

function FileList({ kit }: { kit: PartnerKit }) {
  const rows = kit.assets.flatMap((a) => [a.video, ...(a.endframe ? [a.endframe] : [])]);
  if (kit.guideFile) rows.push(kit.guideFile);
  return (
    <ul className="mt-auto flex flex-col gap-1.5 border-t border-rim-soft pt-3">
      {rows.map((f) => (
        <li key={f.name} className="flex min-w-0 items-center gap-2 text-[11.5px]">
          <Icon name={f.name.endsWith(".mp4") ? "video" : f.name.endsWith(".txt") ? "file" : "eye"} size={12} className="flex-none" />
          <a href={kitFileUrl(kit.code, f.name, true)} className="mono min-w-0 flex-1 truncate text-tx-dim hover:text-white">{f.name}</a>
          <span className="flex-none text-tx-faint">{fmtSize(f.sizeBytes)}</span>
        </li>
      ))}
    </ul>
  );
}

function SubHead({ icon, title, sub }: { icon: string; title: string; sub?: string | null }) {
  return (
    <span className="flex min-w-0 items-start gap-2">
      <Icon name={icon} size={14} className="mt-[2px] flex-none" />
      <span className="flex min-w-0 flex-col">
        <span className="text-[13px] font-extrabold tracking-[-0.01em] text-white">{title}</span>
        {sub && <span className="text-[11px] text-tx-faint">{sub}</span>}
      </span>
    </span>
  );
}

function GuideBlocks({ guide, kit, showAbout }: { guide: KitGuide; kit: PartnerKit; showAbout: boolean }) {
  return (
    <div className="flex min-w-0 flex-col gap-3">
      {showAbout && (guide.whatItIs || guide.filesNote) && (
        <div className="rounded-[12px] border border-rim-soft bg-well p-4">
          <SubHead icon="sparkles" title="What it is" />
          {guide.whatItIs && <p className="mt-2 text-[12.5px] leading-relaxed text-tx-mute">{guide.whatItIs}</p>}
          {guide.filesNote && <p className="mt-2 text-[12px] leading-relaxed text-tx-faint">{guide.filesNote}</p>}
        </div>
      )}

      <div className="grid min-w-0 gap-3 lg:grid-cols-2">
        {guide.steps.length > 0 && (
          <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
            <SubHead icon="checkcircle" title="How to use it" />
            <ol className="mt-3 flex flex-col gap-2.5">
              {guide.steps.map((s, i) => (
                <li key={i} className="flex items-start gap-2.5">
                  <span className="grid h-[22px] w-[22px] flex-none place-items-center rounded-full border border-[#8b5cff]/60 bg-[rgba(139,92,255,0.14)] text-[11px] font-extrabold text-white">
                    {i + 1}
                  </span>
                  <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{s}</span>
                </li>
              ))}
            </ol>
          </div>
        )}

        {guide.narration.length > 0 && (
          <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
            <SubHead icon="mic" title="Suggested narration" sub={guide.narrationNote ? cap(guide.narrationNote) : null} />
            <ol className="mt-3 flex flex-col">
              {guide.narration.map((n, i) => (
                <li key={i} className="flex items-start gap-3 border-t border-rim-soft py-2 first:border-t-0 first:pt-0 last:pb-0">
                  <span className="mono w-[42px] flex-none rounded-[6px] border border-rim-hi bg-[rgba(95,208,255,0.08)] py-[2px] text-center text-[11px] font-bold text-cyan">
                    {n.at}
                  </span>
                  <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{n.text}</span>
                </li>
              ))}
            </ol>
          </div>
        )}
      </div>

      {guide.description && <DescriptionBox text={guide.description} />}

      {guide.extra.map((e) => (
        <div key={e.heading} className="rounded-[12px] border border-rim-soft bg-well p-4">
          <SubHead icon="file" title={e.heading} />
          <p className="mt-2 whitespace-pre-line text-[12.5px] leading-relaxed text-tx-mute">{e.body}</p>
        </div>
      ))}

      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-[11.5px] text-tx-faint">
        {guide.contact && (
          <span className="flex min-w-0 items-center gap-1.5">
            <Icon name="envelope" size={12} className="flex-none" />
            Questions?{" "}
            {/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guide.contact) ? (
              <a href={`mailto:${guide.contact}`} className="font-semibold text-cyan hover:text-white">{guide.contact}</a>
            ) : (
              <span className="text-tx-dim">{guide.contact}</span>
            )}
          </span>
        )}
        {kit.guideFile && (
          <a href={kitFileUrl(kit.code, kit.guideFile.name, true)} className="flex items-center gap-1.5 font-semibold text-cyan hover:text-white sm:ml-auto">
            <Icon name="download" size={12} tone="inherit" /> Download this guide (.txt)
          </a>
        )}
      </div>
    </div>
  );
}

function DescriptionBox({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch { /* clipboard blocked — the text is still selectable */ }
  };
  return (
    <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <SubHead icon="copy" title="Description text" sub="Paste it into your video description, with the paid-promotion box ticked." />
        <button type="button" onClick={copy} className="btn-primary h-[34px] flex-none gap-1.5 px-3.5 text-[12.5px]">
          <Icon name={copied ? "check" : "copy"} size={13} tone="inherit" /> {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <p className="mt-3 whitespace-pre-line break-words rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.5)] px-3.5 py-3 text-[12.5px] leading-relaxed text-white select-all">
        {text}
      </p>
    </div>
  );
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function fmtSize(n: number): string {
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${n} B`;
}

