          <SubHead icon="sparkles" title="What it is" />
          {guide.whatItIs && <p className="mt-2 text-[12.5px] leading-relaxed text-tx-mute">{guide.whatItIs}</p>}
          {guide.filesNote && <p className="mt-2 text-[12px] leading-relaxed text-tx-faint">{guide.filesNote}</p>}
        </div>
      )}

      <div className="grid min-w-0 gap-3 lg:grid-cols-2">
        {guide.steps.length > 0 && (
          <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
            <SubHead icon="checkcircle" title="How to use it" />
            <ol className="mt-3 flex flex-col gap-2.5">
              {guide.steps.map((s, i) => (
                <li key={i} className="flex items-start gap-2.5">
                  <span className="grid h-[22px] w-[22px] flex-none place-items-center rounded-full border border-[#8b5cff]/60 bg-[rgba(139,92,255,0.14)] text-[11px] font-extrabold text-white">
                    {i + 1}
                  </span>
                  <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{s}</span>
                </li>
              ))}
            </ol>
          </div>
        )}

        {guide.narration.length > 0 && (
          <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
            <SubHead icon="mic" title="Suggested narration" sub={guide.narrationNote ? cap(guide.narrationNote) : null} />
            <ol className="mt-3 flex flex-col">
              {guide.narration.map((n, i) => (
                <li key={i} className="flex items-start gap-3 border-t border-rim-soft py-2 first:border-t-0 first:pt-0 last:pb-0">
                  <span className="mono w-[42px] flex-none rounded-[6px] border border-rim-hi bg-[rgba(95,208,255,0.08)] py-[2px] text-center text-[11px] font-bold text-cyan">
                    {n.at}
                  </span>
                  <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{n.text}</span>
                </li>
              ))}
            </ol>
          </div>
        )}
      </div>

      {guide.description && <DescriptionBox text={guide.description} />}

      {guide.extra.map((e) => (
        <div key={e.heading} className="rounded-[12px] border border-rim-soft bg-well p-4">
          <SubHead icon="file" title={e.heading} />
          <p className="mt-2 whitespace-pre-line text-[12.5px] leading-relaxed text-tx-mute">{e.body}</p>
        </div>
      ))}

      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-[11.5px] text-tx-faint">
        {guide.contact && (
          <span className="flex min-w-0 items-center gap-1.5">
            <Icon name="envelope" size={12} className="flex-none" />
            Questions?{" "}
            {/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guide.contact) ? (
              <a href={`mailto:${guide.contact}`} className="font-semibold text-cyan hover:text-white">{guide.contact}</a>
            ) : (
              <span className="text-tx-dim">{guide.contact}</span>
            )}
          </span>
        )}
        {kit.guideFile && (
          <a href={kitFileUrl(kit.code, kit.guideFile.name, true)} className="flex items-center gap-1.5 font-semibold text-cyan hover:text-white sm:ml-auto">
            <Icon name="download" size={12} tone="inherit" /> Download this guide (.txt)
          </a>
        )}
      </div>
    </div>
  );
}

function DescriptionBox({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch { /* clipboard blocked — the text is still selectable */ }
  };
  return (
    <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <SubHead icon="copy" title="Description text" sub="Paste it into your video description, with the paid-promotion box ticked." />
        <button type="button" onClick={copy} className="btn-primary h-[34px] flex-none gap-1.5 px-3.5 text-[12.5px]">
          <Icon name={copied ? "check" : "copy"} size={13} tone="inherit" /> {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <p className="mt-3 whitespace-pre-line break-words rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.5)] px-3.5 py-3 text-[12.5px] leading-relaxed text-white select-all">
        {text}
      </p>
    </div>
  );
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function fmtSize(n: number): string {
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${n} B`;
}

