test("kitZip is a valid STORE zip with exact length and CRCs", async () => {
  const z = await kits.kitZip("AIXLL50");
  assert.ok(z);
  assert.equal(z.filename, "nxeon-sponsored-segment-AIXLL50.zip");
  const chunks: Uint8Array[] = [];
  const reader = z.stream.getReader();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
  }
  const buf = Buffer.concat(chunks);
  assert.equal(buf.length, z.size);
  const eocd = buf.length - 22;
  assert.equal(buf.readUInt32LE(eocd), 0x06054b50);
  const count = buf.readUInt16LE(eocd + 10);
  assert.equal(count, 5);
  let p = buf.readUInt32LE(eocd + 16);
  for (let i = 0; i < count; i++) {
    assert.equal(buf.readUInt32LE(p), 0x02014b50);
    const size = buf.readUInt32LE(p + 24);
    const nameLen = buf.readUInt16LE(p + 28);
    const local = buf.readUInt32LE(p + 42);
    const name = buf.subarray(p + 46, p + 46 + nameLen).toString("utf8");
    assert.ok(name.startsWith("nxeon-sponsored-segment-AIXLL50/"));
