// Throwaway-DB seed for the media-kit test (node-2 only, never committed).
import { PrismaClient } from "@prisma/client";
import { SignJWT } from "jose";
import { writeFileSync } from "node:fs";
if (!/127\.0\.0\.1:5433\/wt_/.test(process.env.DATABASE_URL ?? "")) throw new Error("not the throwaway DB");
const db = new PrismaClient();
const now = new Date();
async function user(email: string, name: string, role: "CUSTOMER" | "ADMIN" = "CUSTOMER") {
  return db.user.upsert({ where: { email }, update: {}, create: { email, name, role, emailVerifiedAt: now, passwordHash: "x" } });
}
async function main() {
  const zero = await user("kit-zeroster@example.test", "Zero Ster");
  const aix = await user("kit-aixll50@example.test", "Aix LL");
  const none = await user("kit-nokit@example.test", "No Kit Yet");
  const cust = await user("kit-customer@example.test", "Plain Customer");
  const admin = await user("kit-admin@example.test", "Kit Admin", "ADMIN");
  const partners: Record<string, string> = {};
  for (const [u, code, name] of [[zero, "ZEROSTER", "ZeroSter"], [aix, "AIXLL50", "Aixll"], [none, "NOKIT9", "No Kit Creator"]] as const) {
    const p = await db.referralPartner.upsert({ where: { code }, update: {}, create: { code, name, userId: u.id, commissionRatePct: 40, type: "kol" } });
    partners[code] = p.id;
  }
  const tokens: Record<string, string> = {};
  for (const [k, u] of Object.entries({ zero, aix, none, cust, admin })) {
    tokens[k] = await new SignJWT({ sub: u.id, sv: u.sessionVersion ?? 0, typ: "session" })
      .setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("6h")
      .sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  }
  writeFileSync("_kit-test/tokens.json", JSON.stringify({ tokens, partners }, null, 2));
  console.log("seeded", Object.keys(partners));
}
main().finally(() => db.$disconnect());
EOF
