// Media-kit screenshots ON node-2 against the throwaway DB. Never committed.
import { chromium } from "playwright";
import fs from "node:fs";
const BASE = `http://127.0.0.1:${process.env.PORT ?? 4515}`;
const OUT = "_kit-test/shots";
fs.mkdirSync(OUT, { recursive: true });
const { tokens, partners } = JSON.parse(fs.readFileSync("_kit-test/tokens.json", "utf8"));
const cookieName = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
const browser = await chromium.launch();
const jobs = [];
for (const [who, tk] of [["zeroster", "zero"], ["nokit", "none"], ["aixll50", "aix"]]) {
  for (const w of [1440, 390]) for (const theme of ["dark", "light"]) {
    if (who === "aixll50" && theme === "light" && w === 390) continue;
    jobs.push({ name: `media-${who}-${w}-${theme}`, tk, w, theme, path: "/dashboard/partner?tab=media" });
  }
}
jobs.push({ name: "admin-partner-zeroster-1440", tk: "admin", w: 1440, theme: "dark", path: `/admin/partners/${partners.ZEROSTER}`, clip: "media" });
jobs.push({ name: "admin-partner-nokit-1440", tk: "admin", w: 1440, theme: "dark", path: `/admin/partners/${partners.NOKIT9}`, clip: "media" });
const results = [];
for (const j of jobs) {
  const ctx = await browser.newContext({ viewport: { width: j.w, height: 900 }, deviceScaleFactor: 1 });
  await ctx.addCookies([{ name: cookieName, value: tokens[j.tk], domain: "127.0.0.1", path: "/", httpOnly: true }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); } catch {} }, j.theme);
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  const res = await page.goto(BASE + j.path, { waitUntil: "networkidle", timeout: 240_000 });
  await page.waitForTimeout(1500);
  const info = await page.evaluate(async () => {
    const vids = [...document.querySelectorAll("video")];
    await Promise.all(vids.map((v) => v.readyState >= 1 ? null : new Promise((r) => { v.addEventListener("loadedmetadata", r, { once: true }); v.addEventListener("error", r, { once: true }); setTimeout(r, 8000); })));
    let seek = null;
    if (vids[0] && vids[0].readyState >= 1) {
      seek = await new Promise((r) => { const v = vids[0]; v.addEventListener("seeked", () => r(v.currentTime), { once: true }); setTimeout(() => r("timeout"), 8000); v.currentTime = 30; });
    }
    return {
      overflow: document.documentElement.scrollWidth - window.innerWidth,
      theme: document.documentElement.getAttribute("data-theme"),
      videos: vids.map((v) => ({ ready: v.readyState, dur: Math.round(v.duration || 0), err: v.error?.code ?? null, poster: !!v.poster })),
      canMp4: document.createElement("video").canPlayType('video/mp4; codecs="avc1.42E01E"'),
      seekTo30: seek,
    };
  });
  if (vids0Reset) {}
  // put the first video back to its poster frame for the screenshot
  await page.evaluate(() => { const v = document.querySelector("video"); if (v) { v.load(); } });
  await page.waitForTimeout(800);
  if (j.clip === "media") {
    const card = page.locator(".card", { hasText: "Media kit files" }).first();
    await card.scrollIntoViewIfNeeded();
    await card.screenshot({ path: `${OUT}/${j.name}.png` });
  } else {
    await page.screenshot({ path: `${OUT}/${j.name}.png`, fullPage: true });
  }
  results.push({ name: j.name, status: res?.status(), ...info, errors });
  console.log(JSON.stringify(results.at(-1)));
  await ctx.close();
}
await browser.close();
fs.writeFileSync(`${OUT}/results.json`, JSON.stringify(results, null, 2));
EOF
